using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.IO.Compression;
using System.Linq;
using Microsoft.JSInterop;
using Microsoft.Xna.Framework;
using Microsoft.Xna.Framework.Graphics;
using RenderingLibrary.Content;

namespace KniGumFromFile;

// SPIKE #6156 (not for merge). Raw premultiplied RGBA stored in gum.pkg: inflate (or Brotli) then upload.
// Blobs are generated by Samples/KniGumFromFile/PkgBench into wwwroot/Content/pkgbench.
public static class PkgLoadBench
{
    static readonly (string name, int w, int h)[] Images = { ("bench1024", 1024, 1024), ("hytale", 960, 960), ("MainSpriteSheet", 512, 256) };
    const int Reps = 6; // first is warmup

    static byte[] Fetch(string path)
    {
        using var s = TitleContainer.OpenStream(path);
        using var ms = new MemoryStream();
        s.CopyTo(ms);
        return ms.ToArray();
    }

    static byte[] Inflate(byte[] blob, int len)
    {
        var o = new byte[len];
        using var z = new DeflateStream(new MemoryStream(blob), CompressionMode.Decompress);
        int n = 0; while (n < len) { int r = z.Read(o, n, len - n); if (r <= 0) break; n += r; }
        return o;
    }

    static byte[] BrotliSharp(byte[] blob, int len)
    {
        var o = new byte[len];
        using var z = new BrotliSharpLib.BrotliStream(new MemoryStream(blob), CompressionMode.Decompress);
        int n = 0; while (n < len) { int r = z.Read(o, n, len - n); if (r <= 0) break; n += r; }
        return o;
    }

    static void UnfilterUp(byte[] d, int w)
    {
        int stride = w * 4;
        for (int i = stride; i < d.Length; i++) d[i] = (byte)(d[i] + d[i - stride]);
    }

    static void UnfilterSub(byte[] d)
    {
        for (int i = 4; i < d.Length; i++) d[i] = (byte)(d[i] + d[i - 4]);
    }

    static double Upload(GraphicsDevice device, byte[] rgba, int w, int h)
    {
        var sw = Stopwatch.StartNew();
        var t = new Texture2D(device, w, h, false, SurfaceFormat.Color);
        t.SetData(rgba);
        double ms = sw.Elapsed.TotalMilliseconds;
        t.Dispose();
        return ms;
    }

    public static void Run(IJSRuntime js, GraphicsDevice device, Action<string> log)
    {
        var jsSync = (IJSInProcessRuntime)js;
        log("PKGBENCH DecompressionStream " + jsSync.Invoke<string>("gumDecompressionStreamFormats"));
        try
        {
            var probe = new byte[16];
            BrotliDecoder.TryDecompress(Fetch("Content/pkgbench/MainSpriteSheet.br11.bin"), probe, out _);
            log("PKGBENCH BCL BrotliDecoder works");
        }
        catch (Exception e) { log("PKGBENCH BCL BrotliDecoder throws " + e.GetType().Name + ": " + e.Message); }

        foreach (var (name, w, h) in Images)
        {
            int len = w * h * 4;
            var blob = new Dictionary<string, byte[]>();
            var fetch = new Dictionary<string, double>();
            foreach (var k in new[] { "deflO", "deflF", "upDeflO", "subDeflO", "br11", "br4", "upBr11", "pngBr4" })
            {
                var sw0 = Stopwatch.StartNew();
                blob[k] = Fetch($"Content/pkgbench/{name}.{k}.bin");
                fetch[k] = sw0.Elapsed.TotalMilliseconds;
            }
            log($"PKGBENCH {name} bytes " + string.Join(" ", blob.Select(kv => $"{kv.Key}={kv.Value.Length}")) + " fetchMs " + string.Join(" ", fetch.Select(kv => $"{kv.Key}={kv.Value:F1}")));

            var r = new Dictionary<string, List<double>>();
            void Add(string k, double v) { if (!r.TryGetValue(k, out var l)) r[k] = l = new List<double>(); l.Add(v); }
            for (int rep = 0; rep < Reps; rep++)
            {
                var sw = new Stopwatch();
                double Lap() { var e = sw.Elapsed.TotalMilliseconds; sw.Restart(); return e; }
                var row = new List<(string, double)>();

                sw.Restart(); var a = Inflate(blob["deflO"], len); row.Add(("deflO.inflate", Lap())); row.Add(("deflO.upload", Upload(device, a, w, h)));
                sw.Restart(); a = Inflate(blob["deflF"], len); row.Add(("deflF.inflate", Lap())); row.Add(("deflF.upload", Upload(device, a, w, h)));
                sw.Restart(); a = Inflate(blob["upDeflO"], len); row.Add(("upDeflO.inflate", Lap())); UnfilterUp(a, w); row.Add(("upDeflO.unfilter", Lap()));
                sw.Restart(); a = Inflate(blob["subDeflO"], len); row.Add(("subDeflO.inflate", Lap())); UnfilterSub(a); row.Add(("subDeflO.unfilter", Lap()));
                sw.Restart(); a = BrotliSharp(blob["br11"], len); row.Add(("br11.BrotliSharpLib", Lap()));
                sw.Restart(); a = BrotliSharp(blob["br4"], len); row.Add(("br4.BrotliSharpLib", Lap()));
                sw.Restart(); a = jsSync.Invoke<byte[]>("gumBrotliJs", blob["br11"]); row.Add(("br11.js(incl interop)", Lap()));
                if (a.Length != len) log($"PKGBENCH {name} js length mismatch {a.Length}");
                row.Add(("br11.js(inside JS)", jsSync.Invoke<double>("gumBrotliJsTimed", blob["br11"])));
                sw.Restart(); a = jsSync.Invoke<byte[]>("gumBrotliJs", blob["upBr11"]); row.Add(("upBr11.js", Lap())); UnfilterUp(a, w); row.Add(("upBr11.unfilter", Lap()));

                // Baseline: PNG inside today's gum.pkg (whole-archive Brotli via BrotliSharpLib), then the current
                // ContentLoader premultiplied path (B: FromStream + GetData + premultiply + SetData).
                sw.Restart(); var png = BrotliSharp(blob["pngBr4"], blob["pngBr4"].Length * 2 + 1024);
                row.Add(("png.pkgBrotli", Lap()));
                var tb = Texture2D.FromStream(device, new MemoryStream(png)); row.Add(("png.B.decode", Lap()));
                var pb = new Color[tb.Width * tb.Height]; tb.GetData(pb); TexturePremultiply.Premultiply(pb); tb.SetData(pb); row.Add(("png.B.readPremulUpload", Lap()));
                tb.Dispose();

                if (rep == 0) continue;
                foreach (var (k, v) in row) Add(k, v);
            }
            foreach (var kv in r)
            {
                var sorted = kv.Value.OrderBy(v => v).ToList();
                log($"PKGBENCH {name} {kv.Key} median={sorted[sorted.Count / 2]:F1} all=[{string.Join(",", kv.Value.Select(v => v.ToString("F1")))}]");
            }
        }
        log("PKGBENCH DONE");
    }
}
